"""Gauss-sum vanishing under imprimitivity (mod 9 case study).

Demonstrates Theorems 5.1 and 5.2: a Gauss sum against an imprimitive
additive character survives EXACTLY when the Dirichlet character is
imprimitive.  Self-contained; standard library only.
"""
from __future__ import annotations
import cmath, math
from typing import Dict, List, Callable

def gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a

def units_mod(n: int) -> List[int]:
    return [a for a in range(1, n + 1) if gcd(a, n) == 1]

def primitive_root(n: int) -> int:
    us = units_mod(n); order = len(us)
    for g in us:
        seen, x = set(), 1 % n
        for _ in range(order):
            x = (x * g) % n; seen.add(x)
        if len(seen) == order:
            return g
    raise ValueError("no primitive root")

def characters_mod(n: int) -> List[Dict[int, complex]]:
    g = primitive_root(n); us = units_mod(n); order = len(us)
    dlog: Dict[int, int] = {}; x = 1 % n
    for k in range(order):
        x = (x * g) % n; dlog[x] = (k + 1) % order
    dlog[1 % n] = 0
    chars = []
    for j in range(order):
        chars.append({a: (cmath.exp(2j*math.pi*j*dlog[a]/order) if gcd(a,n)==1 else 0.0)
                      for a in range(n)})
    return chars

def conductor(chi: Dict[int, complex], n: int) -> int:
    for d in range(1, n + 1):
        if n % d: continue
        if all(abs(chi[a]-chi[b]) < 1e-9
               for a in units_mod(n) for b in units_mod(n) if (a-b) % d == 0):
            return d
    return n

def gauss(chi: Dict[int, complex], n: int, a: int) -> complex:
    return sum(chi[x]*cmath.exp(2j*math.pi*a*x/n) for x in range(n))

def main() -> None:
    n = 9
    chars = characters_mod(n)
    print(f"Gauss sums modulo {n} against imprimitive e(x)=exp(2pi i*3x/9):")
    for j, chi in enumerate(chars):
        prim = conductor(chi, n) == n
        g = gauss(chi, n, 3)
        print(f"  chi_{j}: primitive={prim!s:5}  |g|={abs(g):.3f}  "
              f"survives={abs(g) > 1e-9}")
    print("\nConclusion: survival <=> imprimitivity of chi (Theorems 5.1-5.2).")

if __name__ == "__main__":
    main()

"""Root-number reciprocity and the quadratic sign W(chi)^2 = 1.

Verifies numerically that for primitive characters |W(chi)| = 1 and
W(chi) * W(chi^{-1}) = 1, and that for real (quadratic) primitive
characters W(chi) is exactly +1 or -1 (Theorems 4.2 and 4.4).
Self-contained; standard library only.
"""
from __future__ import annotations
import cmath, math
from typing import Dict, List

def gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a

def units_mod(n: int) -> List[int]:
    return [a for a in range(1, n + 1) if gcd(a, n) == 1]

def primitive_root(n: int) -> int:
    us = units_mod(n); order = len(us)
    for g in us:
        seen, x = set(), 1 % n
        for _ in range(order):
            x = (x * g) % n; seen.add(x)
        if len(seen) == order:
            return g
    raise ValueError("no primitive root")

def characters_mod(n: int) -> List[Dict[int, complex]]:
    g = primitive_root(n); us = units_mod(n); order = len(us)
    dlog: Dict[int, int] = {}; x = 1 % n
    for k in range(order):
        x = (x * g) % n; dlog[x] = (k + 1) % order
    dlog[1 % n] = 0
    return [{a: (cmath.exp(2j*math.pi*j*dlog[a]/order) if gcd(a,n)==1 else 0.0)
             for a in range(n)} for j in range(order)]

def conductor(chi: Dict[int, complex], n: int) -> int:
    for d in range(1, n + 1):
        if n % d: continue
        if all(abs(chi[a]-chi[b]) < 1e-9
               for a in units_mod(n) for b in units_mod(n) if (a-b) % d == 0):
            return d
    return n

def root_number(chi: Dict[int, complex], n: int) -> complex:
    g = sum(chi[x]*cmath.exp(2j*math.pi*x/n) for x in range(n))
    return g/abs(g) if abs(g) > 1e-12 else 0.0

def main() -> None:
    for n in (5, 7, 11, 13):
        print(f"\nModulus {n}:")
        for j, chi in enumerate(characters_mod(n)):
            if conductor(chi, n) != n:
                continue
            chi_inv = {a: chi[a].conjugate() for a in range(n)}
            w, w_inv = root_number(chi, n), root_number(chi_inv, n)
            real = all(abs(v.imag) < 1e-9 for v in chi.values())
            prod = w * w_inv
            line = (f"  chi_{j}: |W|={abs(w):.3f}  "
                    f"W*W_inv={prod.real:+.3f}{prod.imag:+.3f}i")
            if real:
                line += f"   [quadratic] W={w.real:+.0f}"
            print(line)

if __name__ == "__main__":
    main()

