from __future__ import annotations
from typing import Dict, List

def gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a

def units_mod(n: int) -> List[int]:
    return [a for a in range(1, n + 1) if gcd(a, n) == 1]

def character_conductor(chi: Dict[int, complex], n: int) -> int:
    """Smallest divisor d | n through which chi factors (the conductor)."""
    for d in range(1, n + 1):
        if n % d != 0:
            continue
        factors = all(
            abs(chi[a] - chi[b]) < 1e-9
            for a in units_mod(n) for b in units_mod(n)
            if (a - b) % d == 0
        )
        if factors:
            return d
    return n

def is_primitive(chi: Dict[int, complex], n: int) -> bool:
    """chi is primitive iff its conductor equals its modulus."""
    return character_conductor(chi, n) == n

from __future__ import annotations
import cmath, math
from typing import Callable, Dict

def gauss_sum(chi: Dict[int, complex], n: int,
              e: Callable[[int], complex]) -> complex:
    """g(chi, e) = sum_{x mod n} chi(x) e(x)."""
    return sum(chi[x] * e(x) for x in range(n))

def standard_add_char(n: int, a: int = 1) -> Callable[[int], complex]:
    """x -> exp(2 pi i a x / n); primitive iff gcd(a, n) = 1."""
    return lambda x: cmath.exp(2j * math.pi * a * x / n)

def root_number(chi: Dict[int, complex], n: int) -> complex:
    """Normalised root number W(chi) = g(chi)/|g(chi)| for primitive chi."""
    g = gauss_sum(chi, n, standard_add_char(n, 1))
    return g / abs(g) if abs(g) > 1e-12 else 0.0

from __future__ import annotations
import cmath, math
from typing import Dict, List

def gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a

def divisors(n: int) -> List[int]:
    return [d for d in range(1, n + 1) if n % d == 0]

def conductor_via_gauss(chi: Dict[int, complex], n: int) -> int:
    """Conductor descent (Theorem 5.3): the conductor is the least divisor d
    such that every additive character trivialised by d has vanishing Gauss
    sum, equivalently the least d through which chi factors as detected by
    surviving Gauss sums against d-trivial additive characters."""
    for d in divisors(n):
        # additive characters trivialised by d: exp(2 pi i (n/d) k x / n)
        step = n // d
        survives = False
        for k in range(1, d):
            e = lambda x, kk=k: cmath.exp(2j * math.pi * step * kk * x / n)
            g = sum(chi[x] * e(x) for x in range(n))
            if abs(g) > 1e-9 and gcd(k, d) == 1:
                survives = True
                break
        # chi factors through d iff it is constant on cosets mod d
        factors = all(
            abs(chi[a] - chi[b]) < 1e-9
            for a in range(n) for b in range(n)
            if gcd(a, n) == 1 and gcd(b, n) == 1 and (a - b) % d == 0
        )
        if factors:
            return d
    return n
